<template>
  <div>
    <el-alert v-if="error" :title="error" type="error" :closable="false" class="mb16" />
    <el-form :inline="true" @submit.prevent="search">
      <el-form-item :label="bilingual('客户','Client')"><el-select v-model="query.client" clearable filterable remote :remote-method="lookup" style="width:260px"><el-option v-for="item in clients" :key="item.id" :label="item.label" :value="item.id" /></el-select></el-form-item>
      <el-form-item><el-button type="primary" :loading="loading" @click="search">{{bilingual('搜索','Search')}}</el-button><el-button v-if="canEdit" :disabled="blocked" @click="openCreate()">{{bilingual('申请调整','Request adjustment')}}</el-button><el-button v-if="admin&&canEdit" :disabled="blocked" @click="policyRef.open()">{{bilingual('贷项政策','Credit policy')}}</el-button></el-form-item>
    </el-form>
    <el-radio-group v-model="kind" class="mb16"><el-radio-button value="adjustments">{{bilingual('调账记录','Adjustments')}}</el-radio-button><el-radio-button value="credit-notes">{{bilingual('贷项单','Credit notes')}}</el-radio-button></el-radio-group>
    <el-table :data="rows" v-loading="loading" border row-key="id">
      <el-table-column :prop="kind==='adjustments'?'reason':'number'" :label="kind==='adjustments'?bilingual('调整原因','Reason'):bilingual('贷项编号','Credit number')" min-width="230" show-overflow-tooltip />
      <el-table-column :label="bilingual('客户','Client')" min-width="170"><template #default="s">{{clients.find(c=>c.id===s.row.client)?.label||s.row.client}}</template></el-table-column>
      <el-table-column :label="bilingual('状态','Status')" min-width="185"><template #default="s">{{adjustmentStatus(s.row.status)}}</template></el-table-column>
      <el-table-column prop="currency" :label="bilingual('币种','Currency')" width="100" />
      <el-table-column v-if="kind==='credit-notes'" :label="bilingual('含税核减','Total credit')" width="140"><template #default="s">{{moneyText(s.row.amount)}}</template></el-table-column>
      <el-table-column :label="bilingual('操作','Actions')" width="100" fixed="right"><template #default="s"><el-button link type="primary" @click="kind==='adjustments'?openDetail(s.row.id):openNote(s.row.id)">{{bilingual('查看','View')}}</el-button></template></el-table-column>
    </el-table>
    <pagination v-show="total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load" />
    <el-drawer v-model="createOpened" :title="bilingual('申请费用调整','Request a charge adjustment')" size="min(700px,100%)" :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving">
      <el-alert v-if="createError" :title="createError" type="error" :closable="false" class="mb16" />
      <el-form label-position="top" :disabled="blocked" @submit.prevent>
        <el-form-item :label="bilingual('原费用编号','Original charge ID')"><el-input v-model="createForm.chargeId" :aria-label="bilingual('原费用编号','Original charge ID')" @input="createSource=null" /><el-button class="mt16" :loading="sourceLoading" @click="readSource">{{bilingual('读取原费用','Load original charge')}}</el-button></el-form-item>
        <el-descriptions v-if="createSource" :column="1" border class="mb16"><el-descriptions-item :label="bilingual('费用','Charge')">{{createSource.charge.description}}</el-descriptions-item><el-descriptions-item :label="bilingual('原金额','Original net')">{{createSource.charge.currency}} {{createSource.charge.amount}}</el-descriptions-item><el-descriptions-item :label="bilingual('剩余金额','Remaining net')">{{createSource.remainingNet}}</el-descriptions-item></el-descriptions>
        <el-form-item :label="bilingual('调整原因','Adjustment reason')"><el-input v-model="createForm.reason" type="textarea" maxlength="2000" :aria-label="bilingual('调整原因','Adjustment reason')" /></el-form-item>
        <el-form-item :label="bilingual('依据编号或说明','Evidence reference')"><el-input v-model="createForm.evidenceRef" maxlength="500" :aria-label="bilingual('依据编号或说明','Evidence reference')" /></el-form-item>
      </el-form>
      <template #footer><el-button :disabled="saving" @click="createOpened=false">{{bilingual('关闭','Close')}}</el-button><el-button type="primary" :loading="saving" :disabled="blocked||!createSource" @click="create">{{bilingual('提交申请','Submit request')}}</el-button></template>
    </el-drawer>
    <el-drawer v-model="detailOpened" :title="bilingual('调账复核','Adjustment review')" size="min(1000px,100%)" :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving">
      <el-alert v-if="detailError" :title="detailError" type="error" :closable="false" class="mb16" />
      <div v-if="detail" v-loading="detailLoading" class="details">
        <el-alert v-if="detail.blocker" :title="detail.blocker" type="warning" :closable="false" class="mb16" />
        <el-descriptions :column="1" border><el-descriptions-item :label="bilingual('状态','Status')">{{adjustmentStatus(detail.status)}}</el-descriptions-item><el-descriptions-item :label="bilingual('原费用编号','Original charge ID')">{{detail.chargeId}}</el-descriptions-item><el-descriptions-item :label="bilingual('申请原因','Request reason')">{{detail.reason}}</el-descriptions-item><el-descriptions-item :label="bilingual('依据','Evidence')">{{detail.evidenceRef}}</el-descriptions-item><el-descriptions-item v-if="detail.replacementInvoice" :label="bilingual('重开账单','Replacement invoice')">{{detail.replacementInvoice}}</el-descriptions-item></el-descriptions>
        <template v-if="detail.status==='REVIEW'&&detail.source">
          <h3>{{bilingual('选择原收费项目','Select original fee components')}}</h3>
          <p class="help">{{bilingual('按原数量核减；只有金额依据的费用按税前金额核减。原单价和税率不能在这里修改。','Reduce original quantities, or net amount for fees with an amount basis. Original rates and VAT cannot be edited here.')}}</p>
          <el-form label-position="top" :disabled="blocked" @submit.prevent>
            <div v-for="(item,index) in form.items" :key="item.key" class="component">
              <el-checkbox v-model="item.selected" :aria-label="bilingual('选择项目','Select component')+' '+(index+1)">{{item.description}}</el-checkbox>
              <p>{{bilingual('原数量','Original quantity')}}: {{item.originalQuantity}} · {{bilingual('已核减','Reduced')}}: {{item.reduced}} · {{bilingual('可处理','Available')}}: {{item.remaining}} · {{bilingual('原单价','Original rate')}}: {{item.rate}}</p>
              <el-row :gutter="16"><el-col :xs="24" :sm="12"><el-form-item :label="item.basis==='NET_AMOUNT'?bilingual('税前金额','Net amount'):bilingual('数量','Quantity')"><el-input v-model="item.quantity" inputmode="decimal" :disabled="!item.selected" :aria-label="bilingual('处理数量','Decision quantity')+' '+(index+1)" /></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item :label="bilingual('处理决定','Decision')"><el-select v-model="item.decision" :disabled="!item.selected" :aria-label="bilingual('处理决定','Decision')+' '+(index+1)"><el-option value="reduce" :label="bilingual('核减','Reduce')" /><el-option value="retain" :label="bilingual('保留','Retain')" /></el-select></el-form-item></el-col></el-row>
              <el-button v-if="item.selected&&!form.items.some(x=>x.id===item.id&&x.key!==item.key)" link type="primary" @click="splitDecision(item)">{{bilingual('同一项目另加保留或核减决定','Add a second decision for this component')}}</el-button>
            </div>
            <el-form-item :label="bilingual('复核说明','Review explanation')"><el-input v-model="form.reason" type="textarea" maxlength="2000" :aria-label="bilingual('复核说明','Review explanation')" /></el-form-item>
            <template v-if="retained.length"><el-form-item :label="bilingual('引用原保留决定','Reference prior retained decisions')"><el-checkbox-group v-model="form.reconsiderationOf"><el-checkbox v-for="effect in retained" :key="effect.id" :value="effect.id">{{effect.reason}} · {{effect.id}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item :label="bilingual('重新核减依据','New evidence for reconsideration')"><el-input v-model="form.reconsiderationReason" type="textarea" maxlength="2000" /></el-form-item></template>
            <el-row v-if="detail.source.invoice?.status==='CONFIRMED'" :gutter="16"><el-col :xs="24" :sm="8"><el-form-item :label="bilingual('开具日期（UTC）','Issue date (UTC)')"><el-date-picker v-model="form.issueDate" type="date" value-format="YYYY-MM-DD" :aria-label="bilingual('开具日期','Issue date')" /></el-form-item></el-col><el-col :xs="24" :sm="8"><el-form-item :label="bilingual('税点日期（UTC）','Tax point date (UTC)')"><el-date-picker v-model="form.taxPointDate" type="date" value-format="YYYY-MM-DD" :aria-label="bilingual('税点日期','Tax point date')" /></el-form-item></el-col><el-col :xs="24" :sm="8"><el-form-item :label="bilingual('会计期间','Accounting period')"><el-date-picker v-model="form.accountingPeriod" type="month" value-format="YYYY-MM" :aria-label="bilingual('会计期间','Accounting period')" /></el-form-item></el-col></el-row>
            <el-button type="primary" plain :loading="previewing" :disabled="blocked" @click="preview">{{bilingual('预览调整结果','Preview adjustment')}}</el-button>
          </el-form>
          <AdjustmentPlan v-if="quote" :plan="quote.plan" class="mt16" />
        </template>
        <template v-if="activeApproval"><h3>{{bilingual('已批准方案','Approved plan')}}</h3><AdjustmentPlan :plan="activeApproval.plan" /><p>{{bilingual('批准人','Approved by')}}: {{activeApproval.actorId}}</p><el-alert v-if="sameActorBlocked" type="info" :closable="false" :title="bilingual('当前政策要求另一位有执行权限的人员完成执行。','The current policy requires a different authorized person to execute this approval.')" /></template>
        <template v-if="detail.creditNotes?.length"><h3>{{bilingual('已生成贷项单','Issued credit notes')}}</h3><el-button v-for="note in detail.creditNotes" :key="note.id" link type="primary" @click="openNote(note.id)">{{note.number}} · {{note.currency}} {{moneyText(note.amount)}}</el-button></template>
        <el-collapse class="mt16"><el-collapse-item v-if="detail.approvals?.length" :title="bilingual('审批历史','Approval history')"><div v-for="approval in detail.approvals" :key="approval.id" class="history"><p>{{adjustmentStatus(approval.status)}} · {{bilingual('批准人','Approved by')}} {{approval.actorId}}</p><AdjustmentPlan :plan="approval.plan" /></div></el-collapse-item><el-collapse-item v-if="detail.source?.effects?.length" :title="bilingual('原费用调整历史','Original charge adjustment history')"><div v-for="effect in detail.source.effects" :key="effect.id" class="history"><p>{{effect.executedAt}} · {{bilingual('执行人','Executed by')}} {{effect.executedBy}}</p><AdjustmentPlan :plan="effect" /></div></el-collapse-item></el-collapse>
      </div>
      <template #footer><div class="actions"><el-button :disabled="saving" @click="detailOpened=false">{{bilingual('关闭','Close')}}</el-button><el-button :disabled="blocked||detailLoading||!detail" @click="openDetail(detail?.id)">{{bilingual('重新读取','Reload')}}</el-button><el-button v-if="detail?.status==='REVIEW'&&canEdit" type="danger" plain :disabled="blocked" @click="act('cancel')">{{bilingual('取消申请','Cancel request')}}</el-button><el-button v-if="detail?.status==='REVIEW'&&canApprove" type="primary" :disabled="blocked||!quote" :loading="saving" @click="act('approve')">{{bilingual('批准此方案','Approve plan')}}</el-button><el-button v-if="detail?.status==='APPROVED'&&canApprove" type="warning" plain :disabled="blocked" @click="act('revoke')">{{bilingual('撤销批准','Revoke approval')}}</el-button><el-button v-if="detail?.status==='APPROVED'&&canExecute" type="primary" :disabled="blocked||sameActorBlocked||!!detail.blocker" :loading="saving" @click="act('execute')">{{bilingual('执行已批准方案','Execute approved plan')}}</el-button></div></template>
    </el-drawer>
    <el-drawer v-model="noteOpened" :title="bilingual('贷项单','Credit note')" size="min(850px,100%)"><el-alert v-if="noteError" :title="noteError" type="error" :closable="false" class="mb16" /><template v-if="note"><el-descriptions :column="1" border><el-descriptions-item :label="bilingual('编号','Number')">{{note.number}}</el-descriptions-item><el-descriptions-item :label="bilingual('原账单','Original invoice')">{{note.originalInvoiceReference}}</el-descriptions-item><el-descriptions-item :label="bilingual('开具方','Seller')">{{note.profile?.seller?.name}} · {{note.profile?.seller?.address}}</el-descriptions-item><el-descriptions-item :label="bilingual('客户','Buyer')">{{note.profile?.buyer?.name}} · {{note.profile?.buyer?.address}}</el-descriptions-item><el-descriptions-item :label="bilingual('开具日期','Issue date')">{{note.profile?.issueDate}}</el-descriptions-item><el-descriptions-item :label="bilingual('原因','Reason')">{{note.reason}}</el-descriptions-item><el-descriptions-item :label="bilingual('税前核减','Net credit')">{{note.currency}} {{moneyText(note.net)}}</el-descriptions-item><el-descriptions-item :label="bilingual('税额核减','Tax credit')">{{moneyText(note.tax)}}</el-descriptions-item><el-descriptions-item :label="bilingual('含税核减','Total credit')">{{moneyText(note.amount)}}</el-descriptions-item></el-descriptions><p>{{bilingual('贷项单保留原账单，不代表已完成现金退款或会计平台同步。','The original invoice remains intact. This note does not confirm a cash refund or accounting-platform synchronization.')}}</p></template><template #footer><el-button @click="noteOpened=false">{{bilingual('关闭','Close')}}</el-button><el-button type="primary" :disabled="!note" @click="printNote">{{bilingual('打印贷项单','Print credit note')}}</el-button></template></el-drawer>
    <AdjustmentPolicy ref="policyRef" />
  </div>
</template>
<script setup>
import {computed,ref,reactive,watch,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import auth from '@/plugins/auth'
import request from '@/utils/request'
import useUserStore from '@/store/modules/user'
import {getWarehouseLookups} from '@/api/warehouse'
import {bilingual,language} from '@/warehouse/i18n'
import {financeBusy,financePending,financePendingError,financeRevision,submitFinance} from '@/warehouse/finance'
import {moneyText,adjustmentStatus,adjustmentPlanInput,creditNoteHtml} from '@/warehouse/adjustments'
import AdjustmentPlan from './adjustment-plan.vue'
import AdjustmentPolicy from './adjustment-policy.vue'
const props=defineProps({targetCharge:Object,targetAdjustment:Object})
const user=useUserStore(),admin=computed(()=>Number(user.id)===1),canEdit=computed(()=>auth.hasPermi('warehouse:finance:edit')),canApprove=computed(()=>auth.hasPermi('warehouse:finance:approveAdjustment')),canExecute=computed(()=>auth.hasPermi('warehouse:finance:executeAdjustment'))
const kind=ref('adjustments'),query=reactive({pageNum:1,pageSize:20,client:''}),rows=ref([]),total=ref(0),clients=ref([]),loading=ref(false),error=ref(''),saving=ref(false),policyRef=ref(),blocked=computed(()=>saving.value||detailLoading.value||financeBusy.value||!!financePending.value||!!financePendingError.value)
const createOpened=ref(false),createError=ref(''),createForm=ref({}),createSource=ref(null),sourceLoading=ref(false),detailOpened=ref(false),detailLoading=ref(false),detailError=ref(''),detail=ref(null),form=ref({items:[]}),quote=ref(null),quotedInput=ref(null),previewing=ref(false),noteOpened=ref(false),noteError=ref(''),note=ref(null)
const activeApproval=computed(()=>detail.value?.status==='APPROVED'?detail.value.approvals?.find(a=>a.id===detail.value.approvalId):null),sameActorBlocked=computed(()=>activeApproval.value&&activeApproval.value.plan.policy?.requireDifferentActor!==false&&String(activeApproval.value.actorId)===String(user.id)),retained=computed(()=>(detail.value?.source?.effects||[]).filter(e=>e.decisions.some(d=>d.decision==='retain'&&Number(d.quantity)>0)))
let generation=0,lookupTicket=0,detailTicket=0,sourceTicket=0,previewTicket=0
async function lookup(q=''){const ticket=++lookupTicket;try{const result=await getWarehouseLookups('clients',q);if(ticket===lookupTicket)clients.value=result.data}catch(e){error.value=e.message}}
async function load(){const ticket=++generation;loading.value=true;error.value='';try{const result=await request({url:'/warehouse/finance/'+kind.value,method:'get',params:{...query}});if(ticket===generation){rows.value=result.rows;total.value=result.total}}catch(e){if(ticket===generation)error.value=e.message}finally{if(ticket===generation)loading.value=false}}
function search(){query.pageNum=1;load()}
function openCreate(charge=''){if(blocked.value||!canEdit.value)return;sourceTicket++;createForm.value={chargeId:charge,reason:'',evidenceRef:''};createSource.value=null;createError.value='';createOpened.value=true;if(charge)readSource()}
async function readSource(){const id=createForm.value.chargeId.trim(),ticket=++sourceTicket;createSource.value=null;sourceLoading.value=true;createError.value='';try{if(!id)throw Error(bilingual('请选择原费用','Choose the original charge'));const result=await request({url:'/warehouse/finance/adjustments/source/'+encodeURIComponent(id),method:'get'});if(ticket===sourceTicket&&createForm.value.chargeId.trim()===id)createSource.value=result.data}catch(e){if(ticket===sourceTicket)createError.value=e.message}finally{if(ticket===sourceTicket)sourceLoading.value=false}}
async function create(){if(blocked.value||!createSource.value)return;saving.value=true;createError.value='';try{if(!createForm.value.reason.trim()||!createForm.value.evidenceRef.trim())throw Error(bilingual('请填写原因及依据','Enter the reason and evidence reference'));const result=await submitFinance({label:bilingual('申请费用调整','Request charge adjustment'),url:'/warehouse/finance/adjustments',method:'post',data:{requestId:crypto.randomUUID(),...createForm.value,chargeId:createSource.value.charge.id}});createOpened.value=false;await openDetail(result.data.id)}catch(e){createError.value=e.message}finally{saving.value=false}}
async function openDetail(id){if(!id)return;const ticket=++detailTicket;detailLoading.value=true;detailError.value='';detailOpened.value=true;quote.value=null;previewTicket++;try{const result=await request({url:'/warehouse/finance/adjustments/'+encodeURIComponent(id),method:'get'});if(ticket!==detailTicket)return;detail.value=result.data;const today=new Date().toISOString().slice(0,10);form.value={reason:detail.value.reason,items:(detail.value.source?.components||[]).map(item=>({...item,key:crypto.randomUUID(),originalQuantity:item.quantity,quantity:item.remaining,decision:'reduce',selected:false})),issueDate:today,taxPointDate:today,accountingPeriod:today.slice(0,7),reconsiderationOf:[],reconsiderationReason:''}}catch(e){if(ticket===detailTicket){detail.value=null;detailError.value=e.message}}finally{if(ticket===detailTicket)detailLoading.value=false}}
function splitDecision(item){form.value.items.push({...item,key:crypto.randomUUID(),quantity:'',selected:true,decision:item.decision==='reduce'?'retain':'reduce'})}
function formError(e){return e.message==='invalid_decimal'?bilingual('数量或金额格式不符，请按原项目精度填写。','Enter a non-negative quantity or amount using the original component precision.'):e.message==='select_adjustment_items'?bilingual('请至少选择一个原收费项目。','Select at least one original fee component.'):e.message}
async function preview(){if(blocked.value)return;detailError.value='';quote.value=null;previewing.value=true;const ticket=++previewTicket;try{const input=adjustmentPlanInput(detail.value,form.value),result=await request({url:'/warehouse/finance/adjustments/'+encodeURIComponent(detail.value.id)+'/preview',method:'post',data:input,headers:{repeatSubmit:false}});if(ticket===previewTicket){quotedInput.value=input;quote.value=result.data}}catch(e){if(ticket===previewTicket)detailError.value=formError(e)}finally{previewing.value=false}}
async function act(action){if(blocked.value||!detail.value)return;saving.value=true;detailError.value='';try{const body={requestId:crypto.randomUUID(),_version:detail.value._version,action};if(action==='approve'){if(!quote.value)return;body.planInput=JSON.parse(JSON.stringify(quotedInput.value));body.quoteHash=quote.value.quoteHash}try{if(['cancel','revoke'].includes(action)){const result=await ElMessageBox.prompt(bilingual('请填写原因，原审批记录会保留。','Enter the reason. Original approval evidence will be retained.'),action==='revoke'?bilingual('撤销批准','Revoke approval'):bilingual('取消申请','Cancel request'),{inputType:'textarea',inputValidator:v=>!!v?.trim()||bilingual('请填写原因','Enter a reason'),confirmButtonText:bilingual('确认','Confirm'),cancelButtonText:bilingual('返回','Back')});body.reason=result.value}else await ElMessageBox.confirm(action==='approve'?bilingual('批准后将占用原费用，直到执行或撤销批准。确认批准此方案？','This approval reserves the original charge until execution or revocation. Approve this plan?'):bilingual('按已批准方案执行调整？原费用和审批证据将保留。','Execute the approved adjustment? Original charges and approval evidence will be retained.'),bilingual('确认操作','Confirm operation'),{type:'warning',confirmButtonText:bilingual('确认','Confirm'),cancelButtonText:bilingual('返回','Back')})}catch{return}await submitFinance({label:bilingual('费用调整：','Charge adjustment: ')+action,url:'/warehouse/finance/adjustments/'+encodeURIComponent(detail.value.id)+'/actions',method:'post',data:body});await openDetail(detail.value.id);ElMessage.success(bilingual('操作已完成','Operation completed'))}catch(e){detailError.value=formError(e)}finally{saving.value=false}}
async function openNote(id){note.value=null;noteOpened.value=true;noteError.value='';try{note.value=(await request({url:'/warehouse/finance/credit-notes/'+encodeURIComponent(id),method:'get'})).data}catch(e){noteError.value=e.message}}
function printNote(){const popup=window.open('','_blank');if(!popup){noteError.value=bilingual('浏览器拦截了打印窗口，请允许弹出窗口。','Allow pop-ups to open the print view.');return}popup.opener=null;popup.document.open();popup.document.write(creditNoteHtml(note.value,language.value==='en'));popup.document.close()}
watch(form,()=>{quote.value=null;quotedInput.value=null;previewTicket++},{deep:true,flush:'sync'})
watch(kind,search);watch(financeRevision,()=>{load();if(detailOpened.value&&detail.value)openDetail(detail.value.id)})
watch(()=>props.targetAdjustment,value=>{if(value?.id)openDetail(value.id)},{immediate:true})
watch(()=>props.targetCharge,value=>{if(value?.id)openCreate(value.id)},{immediate:true})
onMounted(()=>{load();lookup()})
</script>
<style scoped>.mb16{margin-bottom:16px}.mt16{margin-top:16px}h3{font-size:16px;margin:24px 0 12px}.help{color:var(--el-text-color-regular);line-height:1.6}.details{overflow-wrap:anywhere}.component{border:1px solid var(--el-border-color);border-radius:4px;padding:16px;margin-bottom:12px}.component p{color:var(--el-text-color-regular);font-size:13px;line-height:1.7}.component :deep(.el-select),:deep(.el-date-editor){width:100%;max-width:100%}.history{margin-bottom:20px}.actions{display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap}.actions .el-button{margin-left:0}:deep(.el-checkbox){white-space:normal;height:auto;min-height:32px}:deep(.el-checkbox__label){overflow-wrap:anywhere;white-space:normal}@media(max-width:600px){:deep(.el-drawer__body){padding:14px}.component{padding:12px}:deep(.el-form--inline .el-select){max-width:100%}}</style>
